package com.fitness.tracker.service; import com.fitness.tracker.dto.TrackerDtos.*; import com.fitness.tracker.entity.User; import org.springframework.stereotype.Service; import java.util.*; @Service public class RuleBasedAIRecommendationService implements AIRecommendationService {public AIResponse recommend(User u,AIRequest q){boolean loss=q.fitnessGoal().contains("LOSS");var exercises=loss?List.of("Brisk walking or cycling","Bodyweight squats","Push-ups","Plank"):List.of("Squats","Push-ups","Rows or pull-ups","Plank");String plan=q.workoutsPerWeek()+" sessions/week: warm up 5 minutes, train "+Math.max(10,q.availableWorkoutMinutes()-10)+" minutes, cool down 5 minutes.";String calories=loss?"Use a modest calorie deficit and prioritize protein, vegetables, and whole foods.":"Eat balanced meals with adequate protein; adjust portions gradually based on progress.";return new AIResponse(plan,q.workoutsPerWeek(),exercises,calories,"Aim for roughly 2–3 litres of water daily, adjusted for heat and activity.","Keep at least one easier day each week and aim for 7–9 hours of sleep.","Consistency beats perfection—complete the next planned session.","General fitness guidance only; not medical diagnosis or treatment. Consult a qualified professional for individual health concerns.");}}
